import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * <p>The original implementation configured the {@link ParserOptions}
 * inside a synchronized block on a shared {@link Parser} instance.  Because
 * the same {@link Parser} can be reused by multiple threads, there was no
 * guarantee that the security‑related options (e.g. {@code setResolveEntities(false)})
 * were applied before the XML was parsed.  This opened the possibility of an
 * XML External Entity (XXE) attack.</p>
 *
 * <p>The patched version creates a fresh {@link Parser} for each request,
 * builds a dedicated {@link ParserOptions} object with entity resolution
 * explicitly disabled, and passes those options directly to {@code parse}.
 * No synchronization is required and the parser can never be in a state
 * where entity expansion is enabled.</p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // other methods ...

    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a fresh parser instance for this request.
        Parser parser = ATOM_ENGINE.getParser();

        // Build parser options that are safe against XXE.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disable external entity resolution.
        options.setResolveEntities(false);
        // Some Abdera versions also expose an explicit flag for expanding
        // entity references; ensure it is turned off if present.
        try {
            options.getClass()
                   .getMethod("setExpandEntityReferences", boolean.class)
                   .invoke(options, false);
        } catch (ReflectiveOperationException ignored) {
            // Method not present in this version – the resolveEntities flag is sufficient.
        }

        // Parse the input using the securely configured options.
        Document<T> doc = parser.parse(entityStream, options);

        // Return the root element of the parsed document.
        return doc.getRoot();
    }

    // other methods ...

}
