static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Remove query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Normalize the name to eliminate ".." and "." components
    Path normalized = Paths.get(name).normalize();

    // Reject absolute paths
    if (normalized.isAbsolute()) {
        throw new IllegalArgumentException("File name must be a relative path");
    }

    // After normalization, the path must consist of a single name element (no separators)
    if (normalized.getNameCount() != 1) {
        throw new IllegalArgumentException("File name must not contain path separators");
    }

    String safeName = normalized.toString();

    // Build the file under the target directory
    File file = new File(dir, safeName);

    // Ensure the resulting file really resides inside dir (canonical check)
    try {
        String dirCanonical = dir.getCanonicalPath();
        String fileCanonical = file.getCanonicalPath();
        if (!fileCanonical.startsWith(dirCanonical + File.separator)) {
            throw new SecurityException("Resolved file is outside the target directory");
        }
    } catch (IOException e) {
        throw new RuntimeException("Failed to resolve file path", e);
    }

    // Duplicate handling
    int dot = safeName.lastIndexOf('.');
    String prefix = dot < 0 ? safeName : safeName.substring(0, dot);
    String suffix = dot < 0 ? "" : safeName.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Unable to create directories for " + parent);
    }

    return file;
}
