import javax.ws.rs.ext.RuntimeDelegate;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {
    // other methods ...

    /**
     * Validates that a media type token (type or subtype) contains only characters
     * permitted by the HTTP specification (RFC 7230, section 3.2.6).  The allowed
     * characters are the "tchar" set: {@code ! # $ % & ' * + - . ^ _ ` | ~}
     * plus all ASCII letters and digits.  Any control characters, whitespace,
     * or characters outside this whitelist cause validation to fail.
     *
     * @param str the token to validate
     * @return {@code true} if the token consists solely of allowed characters,
     *         {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        // Pre‑computed whitelist of allowed ASCII characters (tchar)
        // 0‑127 range only – any non‑ASCII character is rejected.
        final boolean[] VALID_TOKEN = TokenValidator.VALID_TOKEN;

        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            // Reject non‑ASCII characters outright
            if (c >= VALID_TOKEN.length) {
                return false;
            }
            if (!VALID_TOKEN[c]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Helper class that builds the whitelist once at class‑loading time.
     * This avoids rebuilding the array on every call to {@link #isValid(String)}.
     */
    private static final class TokenValidator {
        private static final boolean[] VALID_TOKEN = new boolean[128];

        static {
            // Digits
            for (char c = '0'; c <= '9'; c++) {
                VALID_TOKEN[c] = true;
            }
            // Upper‑case letters
            for (char c = 'A'; c <= 'Z'; c++) {
                VALID_TOKEN[c] = true;
            }
            // Lower‑case letters
            for (char c = 'a'; c <= 'z'; c++) {
                VALID_TOKEN[c] = true;
            }
            // tchar symbols as defined by RFC 7230
            char[] extra = {
                '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^',
                '_', '`', '|', '~'
            };
            for (char c : extra) {
                VALID_TOKEN[c] = true;
            }
        }

        private TokenValidator() {
            // Utility class – prevent instantiation
        }
    }

    // other methods ...
}
