import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Interceptor that resolves the locale from a request parameter.
 * The implementation validates the supplied value against a whitelist
 * of acceptable locale formats and ensures the resulting Locale is one
 * of the JVM‑supported locales. This prevents malicious input (e.g.
 * script injection) from being turned into a Locale object that could
 * later be rendered unescaped in a view.
 */
public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /** Acceptable locale strings: language (2‑3 letters) optionally followed
     *  by a country (2 letters) and an optional variant. */
    private static final Pattern LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2,3}(?:_[a-zA-Z]{2})?(?:_[\\w]+)?$");

    // other methods ...

    /**
     * Creates a {@link Locale} object from the request param, which might
     * already be a {@link Locale} or a {@link String}. The input is
     * validated against a strict pattern and against the list of locales
     * supported by the JVM. Invalid or unsupported values result in {@code null}
     * and a warning is logged.
     *
     * @param requestedLocale the parameter from the request
     * @return a validated {@link Locale} or {@code null} if the input is
     *         not acceptable
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        // If the caller already supplied a Locale, trust it (it cannot contain XSS payloads)
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale (already Locale): {}", locale);
            return locale;
        }

        // Convert to trimmed string for validation
        String localeStr = requestedLocale.toString().trim();

        // Reject empty strings early
        if (localeStr.isEmpty()) {
            LOG.warn("Requested locale is empty after trimming; ignoring.");
            return null;
        }

        // Validate format against whitelist pattern
        if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
            LOG.warn("Requested locale '{}' does not match allowed pattern; ignoring.", localeStr);
            return null;
        }

        Locale locale;
        try {
            // Use Struts2 helper to build the Locale; it returns null on failure
            locale = LocalizedTextUtil.localeFromString(localeStr, null);
        } catch (Exception e) {
            // Defensive: any unexpected exception should not propagate
            LOG.warn("Exception while parsing locale '{}': {}", localeStr, e.toString());
            return null;
        }

        if (locale == null) {
            LOG.warn("Locale parsing returned null for '{}'; ignoring.", localeStr);
            return null;
        }

        // Ensure the locale is one of the JVM‑supported locales
        boolean supported = false;
        for (Locale available : Locale.getAvailableLocales()) {
            if (available.equals(locale)) {
                supported = true;
                break;
            }
        }
        if (!supported) {
            LOG.warn("Requested locale '{}' is not among the JVM supported locales; ignoring.", localeStr);
            return null;
        }

        LOG.debug("Applied request locale: {}", locale);
        return locale;
    }

    // other methods ...

}
