import com.opensymphony.xwork2.util.logging.LoggerFactory;
import java.util.regex.Pattern;

/**
 * DefaultActionMapper with a hardened {@code cleanupActionName} implementation.
 *
 * The original implementation attempted to “clean” an invalid action name by
 * stripping out the parts that matched the whitelist pattern.  That approach
 * could leave malicious characters untouched and therefore allowed crafted
 * inputs to bypass validation.
 *
 * The patched version follows a strict whitelist strategy: an action name is
 * accepted only if it fully matches the allowed pattern.  Anything else is
 * rejected outright and replaced with a safe empty string.  This eliminates
 * the possibility of partial sanitisation and prevents injection attacks that
 * rely on leftover characters.
 *
 * The method also handles {@code null} inputs gracefully and logs the event
 * without exposing the raw value in production‑level logs.
 */
public class DefaultActionMapper implements ActionMapper {

    private static final Logger LOG = LoggerFactory.getLogger(DefaultActionMapper.class);

    /** Whitelist of characters that are considered safe for an action name. */
    protected final Pattern allowedActionNames = Pattern.compile("[a-zA-Z0-9._!/\\-]*");

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Validates and returns a safe action name.
     *
     * <p>If {@code rawActionName} matches {@link #allowedActionNames} the original
     * value is returned.  Otherwise the method logs a warning and returns an
     * empty string, effectively rejecting the input.  This strict approach avoids
     * the previous “clean‑up” logic that could leave malicious fragments in the
     * result.</p>
     *
     * @param rawActionName action name extracted from the request URI; may be {@code null}
     * @return a validated action name, or an empty string if the input is invalid
     */
    protected String cleanupActionName(final String rawActionName) {
        // Guard against null – treat it as an invalid name.
        if (rawActionName == null) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received null action name; rejecting.");
            }
            return "";
        }

        // Accept only fully‑matching names.
        if (allowedActionNames.matcher(rawActionName).matches()) {
            return rawActionName;
        }

        // Log the rejection; do not attempt any partial sanitisation.
        if (LOG.isWarnEnabled()) {
            LOG.warn(
                "Action/method [{}] does not match allowed action names pattern [{}]; rejecting.",
                rawActionName,
                allowedActionNames.pattern()
            );
        }

        // Return a safe fallback – an empty string indicates “no action”.
        return "";
    }

    // -----------------------------------------------------------------------
    // Remaining methods (omitted for brevity)
    // -----------------------------------------------------------------------
}
