     *         is less than, equal to, or greater than {@code toVersion}
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        int[] from = parseVersionSafely(fromVersion);
        int[] to   = parseVersionSafely(toVersion);

        // Compare major, minor and patch components in order.
        for (int i = 0; i < 3; i++) {
            int diff = from[i] - to[i];
            if (diff != 0) {
                return diff;
            }
        }
        return 0; // versions are equal
    }

