     * minor and patch numbers.
     *
     * <p>The method is defensive:
     * <ul>
     *   <li>If {@code version} is {@code null} or empty, all components are {@code 0}.</li>
     *   <li>If the string contains fewer than three dot‑separated parts,
     *       the missing parts are treated as {@code 0}.</li>
     *   <li>If a part cannot be parsed as an integer, it is treated as {@code 0}
     *       and a warning is logged.</li>
     *   <li>Extra parts beyond the third are ignored.</li>
     * </ul>
     *
     * @param version the version string to parse
     * @return an array of three integers: {major, minor, patch}
     */
    private static int[] parseVersionSafely(String version) {
        int[] result = new int[3]; // defaults to 0

        if (version == null || version.trim().isEmpty()) {
            return result;
        }

        String[] tokens = version.split("\\.");
        int limit = Math.min(tokens.length, 3);

        for (int i = 0; i < limit; i++) {
            String token = tokens[i].trim();
            if (token.isEmpty()) {
                // keep default 0
                continue;
            }
            try {
                result[i] = Integer.parseInt(token);
            } catch (NumberFormatException e) {
                // Log and keep the default 0 for this component.
                LOG.log(Level.WARNING,
                        "Invalid version component ''{0}'' in version string ''{1}''. Treated as 0.",
                        new Object[]{token, version});
            }
        }
        return result;
    }

