        s.add(boolean.class);   s.add(Boolean.class);
        s.add(byte.class);      s.add(Byte.class);
        s.add(short.class);     s.add(Short.class);
        s.add(int.class);       s.add(Integer.class);
        s.add(long.class);      s.add(Long.class);
        s.add(float.class);     s.add(Float.class);
        s.add(double.class);    s.add(Double.class);
        s.add(char.class);      s.add(Character.class);
        // common immutable types
        s.add(String.class);
        s.add(BigDecimal.class);
        s.add(BigInteger.class);
        s.add(Date.class);
        s.add(java.sql.Date.class);
        s.add(java.sql.Timestamp.class);
        s.add(UUID.class);
