        Type componentType;

        if (type instanceof GenericArrayType) {
            GenericArrayType gat = (GenericArrayType) type;
            componentType = gat.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                // Resolve type variable against the parser context.
                componentClass = resolveTypeVariable(parser, (TypeVariable<?>) componentType);
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else {
            // Plain array class (e.g. String[])
            Class<?> arrayClass = (Class<?>) type;
            componentClass = arrayClass.getComponentType();
            componentType = componentClass;
        }

        // -------------------------------------------------------------------
        // 4. Validate the component class against the whitelist.
        // -------------------------------------------------------------------
        if (!isSafeComponentType(componentClass)) {
            String msg = String.format(
                    "Deserialization of array component type %s is not allowed for security reasons.",
                    componentClass);
            throw new IllegalArgumentException(msg);
        }

        // -------------------------------------------------------------------
        // 5. Parse the JSON array using Fastjson (now safe because component
        //    type is whitelisted).
        // -------------------------------------------------------------------
        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        // -------------------------------------------------------------------
        // 6. Convert the JSONArray to a native Java array.
        // -------------------------------------------------------------------
        return (T) toObjectArray(parser, componentClass, array);
    }

    // -----------------------------------------------------------------------
    // Helper methods
    // -----------------------------------------------------------------------

    /**
     * Determines whether the supplied component class is part of the safe
     * whitelist.
     *
     * @param cls the component class to check
     * @return {@code true} if the class is allowed, {@code false} otherwise
     */
    private boolean isSafeComponentType(Class<?> cls) {
        // Primitive arrays (e.g. int[]) are represented by the primitive class.
        // Fastjson will handle them correctly after the whitelist check.
        return SAFE_COMPONENT_TYPES.contains(cls);
    }

    /**
     * Resolves a {@link TypeVariable} to a concrete {@link Class} using the
     * parser's current context.  If resolution fails, {@link Object#class} is
     * returned, which will subsequently be rejected by the whitelist.
     *
     * @param parser   the JSON parser providing the context
     * @param typeVar  the type variable to resolve
     * @return the resolved class, or {@code Object.class} if it cannot be
     *         determined safely
