    private Class<?> resolveTypeVariable(DefaultJSONParser parser, TypeVariable<?> typeVar) {
        Type ctxType = parser.getContext().type;

        if (ctxType instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) ctxType;
            Type raw = pt.getRawType();

            if (raw instanceof Class) {
                Class<?> rawClass = (Class<?>) raw;
                TypeVariable<?>[] vars = rawClass.getTypeParameters();

                for (int i = 0; i < vars.length; i++) {
                    if (vars[i].getName().equals(typeVar.getName())) {
                        Type actual = pt.getActualTypeArguments()[i];
                        if (actual instanceof Class) {
                            return (Class<?>) actual;
                        }
                        // If the actual type is itself a type variable, fall back.
                        break;
                    }
                }
            }
        }

        // Fallback – use the first bound of the type variable.
        Type bound = typeVar.getBounds()[0];
        return TypeUtils.getClass(bound);
    }

