     * Converts a {@link JSONArray} to a native Java array of the specified
     * component type.
     *
     * @param parser          the JSON parser (required for nested deserialization)
     * @param componentType   the component class of the target array
     * @param array           the source {@code JSONArray}
     * @return a Java array containing the elements of {@code array}
     */
    private Object toObjectArray(DefaultJSONParser parser, Class<?> componentType, JSONArray array) {
        // Fastjson already provides a utility for this conversion.
        // The method is kept unchanged; it is safe because the component type
        // has been validated beforehand.
        return array.toArray(componentType);
    }

    // -----------------------------------------------------------------------
    // Other methods required by the interfaces (omitted for brevity)
    // -----------------------------------------------------------------------
}
