@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // -------------------------------------------------------------------------
    // Other conversion methods (omitted for brevity)
    // -------------------------------------------------------------------------

    /**
     * Creates a {@link SAXSource} from a {@link StreamSource} while protecting against
     * XXE attacks. The method disables external entity resolution and disallows DTDs.
     *
     * @param source   the incoming {@link StreamSource}
     * @param exchange the current Camel {@link Exchange} (may be {@code null})
     * @return a securely configured {@link SAXSource}
     * @throws SAXException if a safe {@link XMLReader} cannot be created
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        if (source == null) {
            throw new IllegalArgumentException("StreamSource must not be null");
        }

        // -----------------------------------------------------------------
        // Build the InputSource – either from a Reader or an InputStream.
        // -----------------------------------------------------------------
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else if (source.getInputStream() != null) {
            inputSource = new InputSource(source.getInputStream());
        } else {
            // Neither a Reader nor an InputStream is available – cannot continue.
            throw new IllegalArgumentException("StreamSource does not contain a Reader or InputStream");
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        // ---------------------------------------------------------------
        // Obtain (or create) a SAXParserFactory and apply secure settings.
        // ---------------------------------------------------------------
        SAXParserFactory sfactory = null;
        if (exchange != null) {
            sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
        }
        if (sfactory == null) {
            sfactory = SAXParserFactory.newInstance();
        }

        // The factory must be non‑validating and namespace aware.
        sfactory.setNamespaceAware(true);
        sfactory.setValidating(false);
        // XInclude processing can also lead to external resource loading.
        sfactory.setXIncludeAware(false);

        // -----------------------------------------------------------------
        // Apply the recommended security features. Each feature is set
        // individually so that a failure to set one does not prevent the
        // others from being applied.
        // -----------------------------------------------------------------
        setFactoryFeature(sfactory, XMLConstants.FEATURE_SECURE_PROCESSING, true);
        setFactoryFeature(sfactory, "http://xml.org/sax/features/external-general-entities", false);
        setFactoryFeature(sfactory, "http://xml.org/sax/features/external-parameter-entities", false);
        setFactoryFeature(sfactory, "http://apache.org/xml/features/disallow-doctype-decl", true);
        setFactoryFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        setFactoryFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

        // ---------------------------------------------------------------
        // Create the XMLReader from the factory and enforce the same
        // restrictions on the reader itself (some parsers ignore factory
        // settings for certain features).
        // ---------------------------------------------------------------
        XMLReader xmlReader;
        try {
            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Defensive: repeat the feature configuration on the reader.
            setReaderFeature(xmlReader, "http://xml.org/sax/features/external-general-entities", false);
            setReaderFeature(xmlReader, "http://xml.org/sax/features/external-parameter-entities", false);
            setReaderFeature(xmlReader, "http://apache.org/xml/features/disallow-doctype-decl", true);
            setReaderFeature(xmlReader, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            setReaderFeature(xmlReader, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
        } catch (Exception ex) {
