    // -------------------------------------------------------------------------

    /**
     * Safely sets a feature on a {@link SAXParserFactory}. If the underlying
     * implementation does not support the feature, a warning is logged.
     */
    private static void setFactoryFeature(SAXParserFactory factory, String name, boolean value) {
        try {
            factory.setFeature(name, value);
        } catch (Exception e) {
            LOG.warn("SAXParserFactory does not support feature {} with value {}: {}", name, value, e.toString());
        }
    }

    /**
     * Safely sets a feature on an {@link XMLReader}. If the underlying
     * implementation does not support the feature, a warning is logged.
     */
    private static void setReaderFeature(XMLReader reader, String name, boolean value) {
        try {
            reader.setFeature(name, value);
        } catch (Exception e) {
            LOG.warn("XMLReader does not support feature {} with value {}: {}", name, value, e.toString());
        }
    }

    // -------------------------------------------------------------------------
    // Other conversion methods (omitted for brevity)
    // -------------------------------------------------------------------------
